-- =====================================================================
-- Carga de OCORRENCIAS de exemplo - banco playpark  (649 registros)
-- * Nao usa ids fixos: id_ocorrencia e gerado pelo AUTO_INCREMENT.
-- * Nao cria colaboradores, brinquedos, setores nem usuarios: sorteia
--   entre os que ja existem (colaboradores e usuarios ATIVOS).
-- * Datas em horario de Brasilia, de 03/08/2026 a 20/11/2026,
--   em dias uteis e horario comercial.
-- * Pode ser executado mais de uma vez (cada execucao adiciona 649).
-- =====================================================================

SET NAMES utf8mb4;

-- Os triggers de historico gravam @usuario_logado em historico_ocorrencia.usuario
-- (NOT NULL + FK). Usa o primeiro usuario cadastrado so durante a carga.
SET @usuario_logado = (SELECT MIN(id_usuario) FROM usuario);

-- Marca o ultimo id existente para identificar as linhas criadas pela carga.
SET @id_inicial = (SELECT COALESCE(MAX(id_ocorrencia), 0) FROM ocorrencia);

-- ---------------------------------------------------------------------
-- 1) Tabela temporaria com os dados sorteados (some ao fechar a conexao)
-- ---------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS tmp_seed_ocorrencia;
CREATE TEMPORARY TABLE tmp_seed_ocorrencia (
  seq INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  ordem_producao VARCHAR(50),
  descricao TEXT,
  solucao TEXT,
  data_abertura DATETIME,
  data_atualizacao DATETIME NULL,
  data_conclusao DATETIME NULL,
  rn_colab INT,
  rn_brinq INT,
  fk_prioridade INT,
  fk_status INT,
  rn_user INT,
  atualizado_em DATETIME,
  idx_setor INT
);








-- ---------------------------------------------------------------------
-- 2) Insere em ocorrencia (ids gerados automaticamente, em ordem de data).
--    Colaborador, brinquedo, setor e usuario sao escolhidos entre os
--    registros existentes. Os triggers criam a linha 'CRIACAO' no historico.
-- ---------------------------------------------------------------------
   fk_colaborador, fk_brinquedo, fk_prioridade, fk_status, fk_usuario, criado_em, atualizado_em, fk_setor)
SELECT
  s.ordem_producao, s.descricao, s.solucao, s.data_abertura, s.data_atualizacao, s.data_conclusao,
  c.id_colaborador, b.id_brinquedo, s.fk_prioridade, s.fk_status, u.id_usuario,
  s.data_abertura, s.atualizado_em, st.id_setor
FROM tmp_seed_ocorrencia s
JOIN (SELECT ROW_NUMBER() OVER (ORDER BY id_colaborador) - 1 AS n, id_colaborador
      FROM colaborador WHERE ativo = 1) c
  ON c.n = MOD(s.rn_colab, (SELECT COUNT(*) FROM colaborador WHERE ativo = 1))
JOIN (SELECT ROW_NUMBER() OVER (ORDER BY id_brinquedo) - 1 AS n, id_brinquedo
      FROM brinquedo WHERE brinquedo_ativo = 1) b
  ON b.n = MOD(s.rn_brinq, (SELECT COUNT(*) FROM brinquedo WHERE brinquedo_ativo = 1))
JOIN (SELECT ROW_NUMBER() OVER (ORDER BY id_usuario) - 1 AS n, id_usuario
      FROM usuario WHERE ativo = 1) u
  ON u.n = MOD(s.rn_user, (SELECT COUNT(*) FROM usuario WHERE ativo = 1))
JOIN (SELECT ROW_NUMBER() OVER (ORDER BY id_setor) - 1 AS n, id_setor
      FROM setor) st
  ON st.n = MOD(s.idx_setor, (SELECT COUNT(*) FROM setor))
ORDER BY s.seq;

-- ---------------------------------------------------------------------
-- 3) Corrige data e usuario das linhas 'CRIACAO' geradas pelos triggers
--    (elas sairiam com a hora atual e o usuario da variavel de carga)
-- ---------------------------------------------------------------------
UPDATE historico_ocorrencia h
JOIN ocorrencia o ON o.id_ocorrencia = h.ocorrencia
SET h.data_alteracao = o.data_abertura,
    h.usuario = o.fk_usuario
WHERE h.acao = 'CRIACAO'
  AND h.ocorrencia > @id_inicial;

DROP TEMPORARY TABLE IF EXISTS tmp_seed_ocorrencia;
SET @usuario_logado = NULL;

-- Conferencia
SELECT COUNT(*) AS ocorrencias_criadas FROM ocorrencia WHERE id_ocorrencia > @id_inicial;
SELECT fk_status, COUNT(*) AS total FROM ocorrencia WHERE id_ocorrencia > @id_inicial GROUP BY fk_status;
